    "contracts/diamond/facets/LimitOrderFacet.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../utils/Constants.sol";
import "../../utils/PythHelper.sol";
import "../../utils/TransferHelper.sol";
import "../interfaces/ILimitOrder.sol";
import "../interfaces/IPriceFacade.sol";
import "../interfaces/IPairsManager.sol";
import "../interfaces/ITradingChecker.sol";
import "../libraries/LibLimitOrder.sol";
import "../libraries/LibAccessControlEnumerable.sol";
import {ZERO, ONE, UC, uc, into} from "unchecked-counter/src/UC.sol";

contract LimitOrderFacet is ILimitOrder {

    IPyth private immutable PYTH;

    constructor(IPyth pyth) {
        PYTH = pyth;
    }

    function openLimitOrder(OpenDataInput memory data) external override returns (bytes32 orderHash) {
        return _openLimitOrder(data);
    }

    function openLimitOrderBNB(OpenDataInput memory data) external payable override returns (bytes32 orderHash) {
        data.tokenIn = TransferHelper.nativeWrapped();
        data.amountIn = uint96(msg.value);
        return _openLimitOrder(data);
    }

    function _openLimitOrder(OpenDataInput memory data) private returns (bytes32 orderHash) {
        ITradingChecker(address(this)).openLimitOrderCheck(data);
        return LibLimitOrder.openLimitOrder(data);
    }

    function updateOrderTp(bytes32 orderHash, uint64 takeProfit) public override {
        LimitOrder storage order = LibLimitOrder.limitOrderStorage().limitOrders[orderHash];
        LibLimitOrder.check(order);
        uint256 oldTp = order.takeProfit;
        order.takeProfit = takeProfit;
        emit UpdateOrderTp(msg.sender, orderHash, oldTp, takeProfit);
    }

    function updateOrderSl(bytes32 orderHash, uint64 stopLoss) public override {
        LimitOrder storage order = LibLimitOrder.limitOrderStorage().limitOrders[orderHash];
        LibLimitOrder.check(order);
        require(ITradingChecker(address(this)).checkSl(order.isLong, stopLoss, order.limitPrice), "LimitOrderFacet: stopLoss is not in the valid range");
        uint256 oldSl = order.stopLoss;
        order.stopLoss = stopLoss;
        emit UpdateOrderSl(msg.sender, orderHash, oldSl, stopLoss);
    }

    // stopLoss is allowed to be equal to 0, which means the sl setting is removed.
    // takeProfit must be greater than 0
    function updateOrderTpAndSl(bytes32 orderHash, uint64 takeProfit, uint64 stopLoss) external override {
        updateOrderTp(orderHash, takeProfit);
        updateOrderSl(orderHash, stopLoss);
    }

    function executeLimitOrder(KeeperExecution[] calldata executeOrders) external override {
        LibAccessControlEnumerable.checkRole(Constants.KEEPER_ROLE);
        LibLimitOrder.LimitOrderStorage storage los = LibLimitOrder.limitOrderStorage();
        for (uint256 i; i < executeOrders.length;) {
            _executeLimitOrder(los, executeOrders[i].hash, executeOrders[i].price);
            unchecked {++i;}
        }
    }

    function executeLimitOrder(KeeperExecutionWithPyth[] calldata params) external payable override {
        LibAccessControlEnumerable.checkRole(Constants.KEEPER_ROLE);
        LibLimitOrder.LimitOrderStorage storage los = LibLimitOrder.limitOrderStorage();

        bytes[] memory data = new bytes[](params.length);
        for (uint i = 0; i < params.length; i ++) {
            data[i] = params[i].priceUpdateData;
        }
        PythHelper.updatePythPriceWithMemory(PYTH, data);

        for (uint256 i; i < params.length;) {
            _executeLimitOrder(los, params[i].hash, PythHelper.getPrice(PYTH, params[i].priceId));
            unchecked {++i;}
        }
    }

    function _executeLimitOrder(LibLimitOrder.LimitOrderStorage storage los, bytes32 orderHash, uint64 price) private {
        LimitOrder memory order = los.limitOrders[orderHash];
        if (order.amountIn == 0) {
            return;
        }
        (bool available, uint64 upper, uint64 lower) = IPriceFacade(address(this)).confirmTriggerPrice(order.pairBase, price);
        if (!available) {
            emit ExecuteLimitOrderRejected(order.user, orderHash, ITradingChecker.Refund.SYSTEM);
            return;
        }
        uint64 marketPrice = order.isLong ? upper : lower;

        (bool successful, ITradingChecker.Refund refund, bytes memory data) = ITradingChecker(address(this)).executeLimitOrderCheck(order, marketPrice);
        LibLimitOrder.executeLimitOrder(orderHash, marketPrice, data, successful, refund);
    }

    function cancelLimitOrder(bytes32 orderHash) external override {
        LibLimitOrder.cancelLimitOrder(orderHash);
    }

    function getLimitOrderByHash(bytes32 orderHash) public view override returns (LimitOrderView memory) {
        LimitOrder memory o = LibLimitOrder.limitOrderStorage().limitOrders[orderHash];
        return LimitOrderView(
            orderHash, IPairsManager(address(this)).getPairForTrading(o.pairBase).name, o.pairBase, o.isLong,
            o.tokenIn, o.amountIn, o.qty, o.limitPrice, o.stopLoss, o.takeProfit, o.broker, o.timestamp
        );
    }

    function getLimitOrders(address user, address pairBase) external view override returns (LimitOrderView[] memory) {
        bytes32[] memory orderHashes = LibLimitOrder.limitOrderStorage().userLimitOrderHashes[user];
        // query all
        if (pairBase == address(0)) {
            LimitOrderView[] memory orders = new LimitOrderView[](orderHashes.length);
            for (uint i; i < orderHashes.length; i++) {
                orders[i] = getLimitOrderByHash(orderHashes[i]);
            }
            return orders;
        } else {
            LimitOrderView[] memory _orders = new LimitOrderView[](orderHashes.length);
            UC count = ZERO;
            for (UC i = ZERO; i < uc(orderHashes.length); i = i + ONE) {
                LimitOrderView memory p = getLimitOrderByHash(orderHashes[i.into()]);
                if (p.pairBase == pairBase) {
                    count = count + ONE;
                }
                _orders[i.into()] = p;
            }
            LimitOrderView[] memory orders = new LimitOrderView[](count.into());
            UC index = ZERO;
            for (UC i = ZERO; i < uc(orderHashes.length); i = i + ONE) {
                LimitOrderView memory p = _orders[i.into()];
                if (p.pairBase == pairBase) {
                    orders[index.into()] = p;
                    index = index + ONE;
                }
            }
            return orders;
        }
    }
}
"
    },
    "contracts/diamond/facets/OfflineClearFacet.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../utils/Constants.sol";
import "../interfaces/IOfflineClear.sol";
import "../interfaces/ITrading.sol";
import {RequestType, IPriceFacade} from "../interfaces/IPriceFacade.sol";
import "../libraries/LibAccessControlEnumerable.sol";
import "../libraries/LibTrading.sol";
import "../libraries/LibLimitOrder.sol";
import {ZERO, ONE, UC, uc, into} from "unchecked-counter/src/UC.sol";

// AP-13746 APX V2 offline clearing facet: admin closes leftover positions and cancels leftover
// limit orders on behalf of users.
// Design notes:
//  - Only ADMIN_ROLE may call (the normal path requires msg.sender to be the holder; here that check
//    is replaced by a role check).
//  - Closing keeps the existing async two-step flow: this facet only registers a CLOSE price request;
//    the second step is a normal PRICE_FEEDER feed that triggers closeTradeCallback to settle at the
//    fed market price and returns funds to ot.user. So this facet changes no settlement logic.
//  - Compared with the user-facing closeTrade, this deliberately bypasses the userCloseTrading switch
//    and the pair==CLOSE gate so clearing still works even if those switches are later turned off;
//    only the margin>0 validity check is kept.
//  - Cancelling completes synchronously and refunds the principal to the order owner.
//  - Batch-friendly: positions/orders that no longer exist are silently skipped instead of reverting
//    the whole batch.
contract OfflineClearFacet is IOfflineClear {

    function closeTradeByAdmin(bytes32[] calldata tradeHashes) external override {
        LibAccessControlEnumerable.checkRole(Constants.ADMIN_ROLE);
        LibTrading.TradingStorage storage ts = LibTrading.tradingStorage();
        for (UC i = ZERO; i < uc(tradeHashes.length); i = i + ONE) {
            bytes32 tradeHash = tradeHashes[i.into()];
            ITrading.OpenTrade storage ot = ts.openTrades[tradeHash];
            // Skip if already closed / nonexistent (may have been handled between scan and execution)
            if (ot.margin == 0) {
                continue;
            }
            // Deliberately skip the userCloseTrading and pair-status checks: offline clearing must run
            // under any market switch state. deltaQty matches the user-facing closeTrade (reduce OI).
            IPriceFacade(address(this)).requestPrice(
                tradeHash, ot.pairBase, RequestType.CLOSE,
                ot.isLong ? -(int256(uint256(ot.qty))) : int256(uint256(ot.qty))
            );
            emit AdminCloseTradeRequested(msg.sender, tradeHash, ot.user);
        }
    }

    function cancelLimitOrderByAdmin(bytes32[] calldata orderHashes) external override {
        LibAccessControlEnumerable.checkRole(Constants.ADMIN_ROLE);
        for (UC i = ZERO; i < uc(orderHashes.length); i = i + ONE) {
            bytes32 orderHash = orderHashes[i.into()];
            if (LibLimitOrder.cancelLimitOrderByOperator(orderHash)) {
                emit AdminCancelLimitOrder(msg.sender, orderHash);
            }
        }
    }
}
"
    },
    "contracts/diamond/facets/PairsManagerFacet.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../utils/Constants.sol";
import "../interfaces/IPairsManager.sol";
import "../libraries/LibAccessControlEnumerable.sol";
import {ZERO, ONE, UC, uc, into} from "unchecked-counter/src/UC.sol";

contract PairsManagerFacet is IPairsManager {

    function addPair(
        address base, string calldata name,
        PairType pairType, PairStatus status,
        PairMaxOiAndFundingFeeConfig calldata pairConfig,
        uint16 slippageConfigIndex, uint16 feeConfigIndex,
        LibPairsManager.LeverageMargin[] calldata leverageMargins,
        uint40 longHoldingFeeRate, uint40 shortHoldingFeeRate
    ) external override {
        LibAccessControlEnumerable.checkRole(Constants.PAIR_OPERATOR_ROLE);
        require(base != address(0), "PairsManagerFacet: base cannot be 0 address");
        _leverageMarginsCheck(leverageMargins);
        PairSimple memory ps = PairSimple(name, base, pairType, status);
        LibPairsManager.addPair(ps, slippageConfigIndex, feeConfigIndex, leverageMargins);
        LibPairsManager.updatePairMaxOi(base, pairConfig.maxLongOiUsd, pairConfig.maxShortOiUsd);
        LibPairsManager.updatePairFundingFeeConfig(
            base, pairConfig.fundingFeePerBlockP, pairConfig.minFundingFeeR, pairConfig.maxFundingFeeR
        );
        LibPairsManager.updatePairHoldingFeeRate(base, longHoldingFeeRate, shortHoldingFeeRate);
    }

    function updatePairMaxOi(address base, uint256 maxLongOiUsd, uint256 maxShortOiUsd) external override {
        LibAccessControlEnumerable.checkRole(Constants.MONITOR_ROLE);
        require(base != address(0), "PairsManagerFacet: base cannot be 0 address");
        LibPairsManager.updatePairMaxOi(base, maxLongOiUsd, maxShortOiUsd);
    }

    function batchUpdatePairMaxOi(UpdatePairMaxOiParam[] calldata params) external override {
        LibAccessControlEnumerable.checkRole(Constants.MONITOR_ROLE);
        for (UC i = ZERO; i < uc(params.length); i = i + ONE) {
            UpdatePairMaxOiParam calldata param = params[i.into()];
            require(param.base != address(0), "PairsManagerFacet: base cannot be 0 address");
            LibPairsManager.updatePairMaxOi(param.base, param.maxLongOiUsd, param.maxShortOiUsd);
        }
    }

    function updatePairHoldingFeeRate(address base, uint40 longHoldingFeeRate, uint40 shortHoldingFeeRate) external override {
        LibAccessControlEnumerable.checkRole(Constants.PAIR_OPERATOR_ROLE);
        require(base != address(0), "PairsManagerFacet: base cannot be 0 address");
        LibPairsManager.updatePairHoldingFeeRate(base, longHoldingFeeRate, shortHoldingFeeRate);
    }

    function updatePairFundingFeeConfig(
        address base, uint256 fundingFeePerBlockP, uint256 minFundingFeeR, uint256 maxFundingFeeR
    ) external override {
        LibAccessControlEnumerable.checkRole(Constants.MONITOR_ROLE);
        require(base != address(0), "PairsManagerFacet: base cannot be 0 address");
        LibPairsManager.updatePairFundingFeeConfig(base, fundingFeePerBlockP, minFundingFeeR, maxFundingFeeR);
    }

    function batchUpdatePairFundingFeeConfig(UpdatePairFundingFeeConfigParam[] calldata params) external override {
        LibAccessControlEnumerable.checkRole(Constants.MONITOR_ROLE);
        for (uint256 i = 0; i < params.length;) {
            UpdatePairFundingFeeConfigParam calldata param = params[i];
            require(param.base != address(0), "PairsManagerFacet: base cannot be 0 address");
            LibPairsManager.updatePairFundingFeeConfig(
                param.base, param.fundingFeePerBlockP, param.minFundingFeeR, param.maxFundingFeeR
            );
            unchecked {++i;}
        }
    }

    function removePair(address base) external override {
        LibAccessControlEnumerable.checkRole(Constants.PAIR_OPERATOR_ROLE);
        require(base != address(0), "PairsManagerFacet: base cannot be 0 address");
        LibPairsManager.removePair(base);
    }

    function updatePairStatus(address base, PairStatus status) external override {
        LibAccessControlEnumerable.checkRole(Constants.MONITOR_ROLE);
        _updatePairStatus(base, status);
    }

    function _updatePairStatus(address base, PairStatus status) private {
        require(base != address(0), "PairsManagerFacet: base cannot be 0 address");
        LibPairsManager.updatePairStatus(base, status);
    }

    function updatePairType(address base, PairType pairType) external override {
        LibAccessControlEnumerable.checkRole(Constants.PAIR_OPERATOR_ROLE);
        require(base != address(0), "PairsManagerFacet: base cannot be 0 address");
        LibPairsManager.updatePairType(base, pairType);
    }

    function batchUpdatePairStatus(PairType pairType, PairStatus status) external override {
        LibAccessControlEnumerable.checkRole(Constants.MONITOR_ROLE);
        LibPairsManager.batchUpdatePairStatus(pairType, status);
    }

    function updatePairSlippage(address base, uint16 slippageConfigIndex) external override {
        LibAccessControlEnumerable.checkRole(Constants.PAIR_OPERATOR_ROLE);
        require(base != address(0), "PairsManagerFacet: base cannot be 0 address");
        LibPairsManager.updatePairSlippage(base, slippageConfigIndex);
    }

    function updatePairFee(address base, uint16 feeConfigIndex) external override {
        LibAccessControlEnumerable.checkRole(Constants.PAIR_OPERATOR_ROLE);
        require(base != address(0), "PairsManagerFacet: base cannot be 0 address");
        LibPairsManager.updatePairFee(base, feeConfigIndex);
    }

    function updatePairLeverageMargin(address base, LibPairsManager.LeverageMargin[] calldata leverageMargins) external override {
        LibAccessControlEnumerable.checkRole(Constants.PAIR_OPERATOR_ROLE);
        _updatePairLeverageMargin(base, leverageMargins);
    }

    function _updatePairLeverageMargin(address base, LibPairsManager.LeverageMargin[] calldata leverageMargins) private {
        require(base != address(0), "PairsManagerFacet: base cannot be 0 address");
        _leverageMarginsCheck(leverageMargins);
        LibPairsManager.updatePairLeverageMargin(base, leverageMargins);
    }

    function _leverageMarginsCheck(LibPairsManager.LeverageMargin[] calldata leverageMargins) private pure {
        require(leverageMargins.length > 0, "PairsManagerFacet: Must specify leverage and margin allocation");
        if (leverageMargins.length == 1) {
            LibPairsManager.LeverageMargin memory lm = leverageMargins[0];
            require(lm.tier == 1 && lm.maxLeverage <= 1e3 &&
            lm.liqLostP < 1e4 && lm.initialLostP < lm.liqLostP,
                "PairsManagerFacet: leverageMargins parameter is invalid");
        } else {
            LibPairsManager.LeverageMargin memory lm;
            LibPairsManager.LeverageMargin memory nextLm;
            for (UC i = ZERO; i < uc(leverageMargins.length - 1); i = i + ONE) {
                lm = leverageMargins[i.into()];
                nextLm = leverageMargins[(i + ONE).into()];
                require(
                    lm.tier == (i + ONE).into()
                    && lm.maxLeverage <= 1e3
                    && lm.liqLostP < 1e4 && lm.liqLostP > 1e3
                    && lm.initialLostP < lm.liqLostP
                    && lm.notionalUsd < nextLm.notionalUsd
                    && lm.initialLostP > nextLm.initialLostP
                    && lm.maxLeverage > nextLm.maxLeverage
                    && lm.liqLostP > nextLm.liqLostP,
                    "PairsManagerFacet: leverageMargins parameter is invalid"
                );
            }
            LibPairsManager.LeverageMargin memory lastLm = leverageMargins[leverageMargins.length - 1];
            require(
                lastLm.tier == leverageMargins.length
                && lastLm.maxLeverage <= 1e3
                && lastLm.liqLostP < 1e4 && lastLm.liqLostP > 1e3
                && lastLm.initialLostP < lastLm.liqLostP,
                "PairsManagerFacet: leverageMargins parameter is invalid"
            );
        }
    }

    function safeMode(
        bool openSafeMode, address[] calldata bases, UpdateLeverageParam[] calldata updateLeverages
    ) external override {
        LibAccessControlEnumerable.checkRole(Constants.PAIR_OPERATOR_ROLE);
        if (openSafeMode) {
            for(uint256 i = 0; i < bases.length;) {
                _updatePairStatus(bases[i], PairStatus.CLOSE);
                unchecked {++i;}
            }
        } else {
            for(uint256 i = 0; i < bases.length;) {
                _updatePairStatus(bases[i], PairStatus.AVAILABLE);
                unchecked {++i;}
            }
        }
        for(uint256 i = 0; i < updateLeverages.length;) {
            _updatePairLeverageMargin(updateLeverages[i].base, updateLeverages[i].leverageMargins);
            unchecked {++i;}
        }
    }

    function pairsV4() external view override returns (PairView[] memory) {
        LibPairsManager.PairsManagerStorage storage pms = LibPairsManager.pairsManagerStorage();
        address[] memory bases = pms.pairBases;
        PairView[] memory pairViews = new PairView[](bases.length);
        for (uint i; i < bases.length; i++) {
            LibPairsManager.Pair storage pair = pms.pairs[bases[i]];
            pairViews[i] = _pairToView(pair, pms.slippageConfigs[pair.slippageConfigIndex]);
        }
        return pairViews;
    }

    function getPairByBaseV4(address base) external view override returns (PairView memory) {
        LibPairsManager.PairsManagerStorage storage pms = LibPairsManager.pairsManagerStorage();
        LibPairsManager.Pair storage pair = pms.pairs[base];
        return _pairToView(pair, pms.slippageConfigs[pair.slippageConfigIndex]);
    }

    function _pairToView(
        LibPairsManager.Pair storage pair, LibPairsManager.SlippageConfig memory slippageConfig
    ) private view returns (PairView memory) {
        LibPairsManager.LeverageMargin[] memory leverageMargins = new LibPairsManager.LeverageMargin[](pair.maxTier);
        for (uint16 i = 0; i < pair.maxTier; i++) {
            leverageMargins[i] = pair.leverageMargins[i + 1];
        }
        (LibFeeManager.FeeConfig memory feeConfig,) = LibFeeManager.getFeeConfigByIndex(pair.feeConfigIndex);
        PairView memory pv = PairView(
            pair.name, pair.base, pair.basePosition, pair.pairType, pair.status, pair.maxLongOiUsd, pair.maxShortOiUsd,
            pair.fundingFeePerBlockP, pair.minFundingFeeR, pair.maxFundingFeeR, leverageMargins,
            pair.slippageConfigIndex, pair.slippagePosition, slippageConfig,
            pair.feeConfigIndex, pair.feePosition, feeConfig, pair.longHoldingFeeRate, pair.shortHoldingFeeRate
        );
        return pv;
    }

    function getPairForTrading(address base) external view override returns (TradingPair memory) {
        LibPairsManager.PairsManagerStorage storage pms = LibPairsManager.pairsManagerStorage();
        LibPairsManager.Pair storage pair = pms.pairs[base];
        LeverageMargin[] memory lms = new LeverageMargin[](pair.maxTier);
        for (uint16 i = 0; i < pair.maxTier; i++) {
            LibPairsManager.LeverageMargin memory lm = pair.leverageMargins[i + 1];
            lms[i] = LeverageMargin(lm.notionalUsd, lm.maxLeverage, lm.initialLostP, lm.liqLostP);
        }
        return TradingPair(
            pair.base, pair.name, pair.pairType, pair.status,
            PairMaxOiAndFundingFeeConfig(pair.maxLongOiUsd, pair.maxShortOiUsd, pair.fundingFeePerBlockP, pair.minFundingFeeR, pair.maxFundingFeeR),
            lms,
            _convertSlippage(pms.slippageConfigs[pair.slippageConfigIndex]),
            _convertFeeRate(pair.feeConfigIndex)
        );
    }

    function _convertFeeRate(uint16 feeIndex) private view returns (FeeConfig memory) {
        (LibFeeManager.FeeConfig memory fc,) = LibFeeManager.getFeeConfigByIndex(feeIndex);
        return FeeConfig(fc.openFeeP, fc.closeFeeP, fc.shareP, fc.minCloseFeeP);
    }

    function _convertSlippage(LibPairsManager.SlippageConfig memory sc) private pure returns (SlippageConfigView memory) {
        return SlippageConfigView(
            sc.onePercentDepthAboveUsd, sc.onePercentDepthBelowUsd, sc.slippageLongP, sc.slippageShortP,
            sc.longThresholdUsd, sc.shortThresholdUsd, sc.slippageType
        );
    }

    function getPairConfig(address base) external view override returns (PairMaxOiAndFundingFeeConfig memory) {
        LibPairsManager.Pair storage pair = LibPairsManager.pairsManagerStorage().pairs[base];
        return PairMaxOiAndFundingFeeConfig(pair.maxLongOiUsd, pair.maxShortOiUsd, pair.fundingFeePerBlockP, pair.minFundingFeeR, pair.maxFundingFeeR);
    }

    function getPairFeeConfig(address base) external view override returns (FeeConfig memory) {
        LibPairsManager.PairsManagerStorage storage pms = LibPairsManager.pairsManagerStorage();
        LibPairsManager.Pair storage pair = pms.pairs[base];
        return _convertFeeRate(pair.feeConfigIndex);
    }

    function getPairHoldingFeeRate(address base, bool isLong) external view override returns (uint40 holdingFeeRate) {
        LibPairsManager.Pair storage pair = LibPairsManager.pairsManagerStorage().pairs[base];
        if (isLong) {
            return pair.longHoldingFeeRate;
        } else {
            return pair.shortHoldingFeeRate;
        }
    }

    function getPairSlippageConfig(address base) external view override returns (SlippageConfigView memory) {
        LibPairsManager.PairsManagerStorage storage pms = LibPairsManager.pairsManagerStorage();
        LibPairsManager.Pair storage pair = pms.pairs[base];
        return _convertSlippage(pms.slippageConfigs[pair.slippageConfigIndex]);
    }
}
