    "contracts/diamond/libraries/LibSwapManager.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "../interfaces/IBook.sol";
import "../../utils/TransferHelper.sol";


library LibSwapManager {

    bytes32 constant SWAP_MANAGER_POSITION = keccak256("apollox.swap.manager.storage");

    bytes4 public constant SWAP_SELECTOR = bytes4(keccak256("swap(address,(address,address,address,address,uint256,uint256,uint256),bytes)"));

    using TransferHelper for address;

    struct SwapDescription {
        IERC20 srcToken;
        IERC20 dstToken;
        address payable srcReceiver;
        address payable dstReceiver;
        uint256 amount;
        uint256 minReturnAmount;
        uint256 flags;
    }

    struct SwapManagerStorage {
        address oneInchAggregationRouter;
    }

    function swapManagerStorage() internal pure returns (SwapManagerStorage storage pfs) {
        bytes32 position = SWAP_MANAGER_POSITION;
        assembly {
            pfs.slot := position
        }
    }

    event SetOneInchAggregationRouter(address indexed oldOneInchAggregationRouter, address indexed newOneInchAggregationRouter);

    function setOneInchAggregationRouter(address oneInchAggregationRouter) internal {
        SwapManagerStorage storage pfs = swapManagerStorage();
        address old = pfs.oneInchAggregationRouter;
        pfs.oneInchAggregationRouter = oneInchAggregationRouter;
        emit SetOneInchAggregationRouter(old, oneInchAggregationRouter);
    }

    function oneInchSwap(bytes calldata swapData, IBook.OpenDataInput memory data) internal returns (uint96) {
        // Get data (swapData) from https://api.1inch.dev/swap/v6.0/56/swap without making any changes and pass it to the contract method
        require(bytes4(swapData[0 : 4]) == SWAP_SELECTOR, "invalid 1Inch function selector");

        (, LibSwapManager.SwapDescription memory swapDesc,) = abi.decode(swapData[4 :], (address, LibSwapManager.SwapDescription, bytes));

        require(address(swapDesc.dstToken) == data.tokenIn, "tokenIn is not the same as dstToken");
        require(swapDesc.amount > 0, "invalid amount");
        require(swapDesc.dstReceiver == address(this), "invalid dstReceiver");

        LibSwapManager.SwapManagerStorage storage p = LibSwapManager.swapManagerStorage();
        address(swapDesc.srcToken).transferFrom(msg.sender, swapDesc.amount);
        swapDesc.srcToken.approve(p.oneInchAggregationRouter, swapDesc.amount);
        uint256 beforeBalance = swapDesc.dstToken.balanceOf(address(this));
        (bool succ, bytes memory _data) = address(p.oneInchAggregationRouter).call(swapData);

        require(succ, "1inch call failed");

        uint256 afterBalance = swapDesc.dstToken.balanceOf(address(this));
        (uint256 swapOut,) = abi.decode(_data, (uint256, uint256));
        uint256 diff = afterBalance - beforeBalance;

        uint96 amountOut = uint96(swapOut);
        require(swapOut == diff && swapOut >= swapDesc.minReturnAmount && amountOut == swapOut, "received incorrect token amount or less than minReturnAmount or exceeds maximum value");

        return amountOut;
    }
}
"
    },
    "contracts/diamond/libraries/LibTimeLock.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../utils/Constants.sol";
import "@openzeppelin/contracts/utils/Address.sol";

library LibTimeLock {

    using Address for address;

    bytes32 constant TIME_LOCK_POSITION = keccak256("apollox.time.lock.storage");

    struct Transaction {
        string functionSignature;
        bytes data;
        uint40 executeTime;
        uint40 expiryTime;
    }

    struct TimeLockStorage {
        uint256 salt;
        // hash => Transaction
        mapping(bytes32 => Transaction) transactions;
    }

    function timeLockStorage() internal pure returns (TimeLockStorage storage tls) {
        bytes32 position = TIME_LOCK_POSITION;
        assembly {
            tls.slot := position
        }
    }

    event QueueTransaction(bytes32 indexed transactionHash, string functionSignature, bytes data);
    event CancelTransaction(bytes32 indexed transactionHash);
    event ExecuteTransaction(bytes32 indexed transactionHash);

    function queueTransaction(string calldata functionSignature, bytes calldata data) internal {
        TimeLockStorage storage tls = timeLockStorage();
        uint256 executeTime = block.timestamp + Constants.TIME_LOCK_DELAY;
        bytes32 transactionHash = keccak256(abi.encode(functionSignature, data, executeTime, tls.salt));
        require(tls.transactions[transactionHash].executeTime == 0, "LibTimeLock: Transaction already exists");
        tls.salt++;
        tls.transactions[transactionHash] = Transaction(
            functionSignature, data, uint40(executeTime),
            uint40(block.timestamp + Constants.TIME_LOCK_GRACE_PERIOD)
        );
        emit QueueTransaction(transactionHash, functionSignature, data);
    }

    function cancelTransaction(bytes32 transactionHash) internal {
        TimeLockStorage storage tls = timeLockStorage();
        require(tls.transactions[transactionHash].executeTime > 0, "LibTimeLock: Transaction hasn't been queued");
        delete tls.transactions[transactionHash];
        emit CancelTransaction(transactionHash);
    }

    function executeTransaction(bytes32 transactionHash) internal returns (bytes memory) {
        TimeLockStorage storage tls = timeLockStorage();
        require(tls.transactions[transactionHash].executeTime > 0, "LibTimeLock: Transaction hasn't been queued");
        require(block.timestamp >= tls.transactions[transactionHash].executeTime, "LibTimeLock: Transaction hasn't surpassed time lock");
        require(block.timestamp <= tls.transactions[transactionHash].expiryTime, "LibTimeLock: Transaction is stale");

        Transaction storage transaction = tls.transactions[transactionHash];
        bytes memory data;
        if (bytes(transaction.functionSignature).length == 0) {
            data = transaction.data;
        } else {
            data = abi.encodePacked(bytes4(keccak256(bytes(transaction.functionSignature))), transaction.data);
        }
        bytes memory result = address(this).functionCall(data);
        emit ExecuteTransaction(transactionHash);
        delete tls.transactions[transactionHash];
        return result;
    }
}
"
    },
    "contracts/diamond/libraries/LibTrading.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../interfaces/IVault.sol";
import "../interfaces/ITrading.sol";
import "../interfaces/ITradingCore.sol";
import "../interfaces/IPairsManager.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import {ZERO, ONE, UC, uc, into} from "unchecked-counter/src/UC.sol";

library LibTrading {

    using Math for uint256;

    bytes32 constant TRADING_POSITION = keccak256("apollox.trading.storage");

    struct TradingStorage {
        uint256 salt;
        //--------------- pending ---------------
        // tradeHash =>
        mapping(bytes32 => ITrading.PendingTrade) pendingTrades;
        // margin.tokenIn => total amount of all pending trades
        mapping(address => uint256) pendingTradeAmountIns;
        //--------------- open ---------------
        // tradeHash =>
        mapping(bytes32 => ITrading.OpenTrade) openTrades;
        // user => tradeHash[]
        mapping(address => bytes32[]) userOpenTradeHashes;
        // tokenIn =>
        mapping(address => uint256) openTradeAmountIns;
        // tokenIn[]
        address[] openTradeTokenIns;
    }

    function tradingStorage() internal pure returns (TradingStorage storage ts) {
        bytes32 position = TRADING_POSITION;
        assembly {
            ts.slot := position
        }
    }

    function calcFundingFee(
        ITrading.OpenTrade memory ot,
        IVault.MarginToken memory mt,
        uint256 marketPrice
    ) internal view returns (int256 fundingFee) {
        int256 longAccFundingFeePerShare = ITradingCore(address(this)).lastLongAccFundingFeePerShare(ot.pairBase);
        return calcFundingFee(ot, mt, marketPrice, longAccFundingFeePerShare);
    }

    function calcFundingFee(
        ITrading.OpenTrade memory ot,
        IVault.MarginToken memory mt,
        uint256 marketPrice,
        int256 longAccFundingFeePerShare
    ) internal pure returns (int256 fundingFee) {
        int256 fundingFeeUsd;
        if (ot.isLong) {
            fundingFeeUsd = int256(ot.qty * marketPrice) * (longAccFundingFeePerShare - ot.longAccFundingFeePerShare) / 1e18;
        } else {
            fundingFeeUsd = int256(ot.qty * marketPrice) * (longAccFundingFeePerShare - ot.longAccFundingFeePerShare) * (- 1) / 1e18;
        }
        fundingFee = fundingFeeUsd * int256(10 ** mt.decimals) / int256(1e10 * mt.price);
        return fundingFee;
    }

    function increaseOpenTradeAmount(TradingStorage storage ts, address token, uint256 amount) internal {
        address[] storage tokenIns = ts.openTradeTokenIns;
        bool exists;
        for (UC i = ZERO; i < uc(tokenIns.length); i = i + ONE) {
            if (tokenIns[i.into()] == token) {
                exists = true;
                break;
            }
        }
        if (!exists) {
            tokenIns.push(token);
        }
        ts.openTradeAmountIns[token] += amount;
    }

    function calcHoldingFee(ITrading.OpenTrade storage ot, IVault.MarginToken memory mt) internal view returns (uint256) {
        uint256 holdingFee;
        if (ot.holdingFeeRate > 0 && ot.openBlock > 0) {
            // holdingFeeRate 1e12
            holdingFee = uint256(ot.entryPrice) * ot.qty * (block.number - ot.openBlock) * ot.holdingFeeRate * (10 ** mt.decimals) / uint256(1e22 * mt.price);
        }
        return holdingFee;
    }

    function calcCloseFee(
        IPairsManager.FeeConfig memory feeConfig, IVault.MarginToken memory mt,
        uint256 closeNotionalUsd, int256 pnl
    ) internal pure returns (uint256) {
        if (feeConfig.shareP > 0 && feeConfig.minCloseFeeP > 0) {
            // closeFeeUsd = max(pnlUsd * shareP, minCloseFeeP * notionalUsd)
            uint256 minCloseFeeUsd = closeNotionalUsd * feeConfig.minCloseFeeP;
            if (pnl <= 0) {
                return minCloseFeeUsd * (10 ** mt.decimals) / (1e5 * 1e10 * mt.price);
            } else {
                uint256 closeFeeUsd = uint256(pnl) * mt.price * feeConfig.shareP * 1e10 / (10 ** mt.decimals);
                return closeFeeUsd.max(minCloseFeeUsd) * (10 ** mt.decimals) / (1e5 * 1e10 * mt.price);
            }
        } else {
            return closeNotionalUsd * feeConfig.closeFeeP * (10 ** mt.decimals) / (1e4 * 1e10 * mt.price);
        }
    }
}
"
    },
    "contracts/diamond/libraries/LibTradingConfig.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../interfaces/IPriceFacade.sol";
import {MaxTpRatioForLeverage} from "../interfaces/ITradingConfig.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import {ZERO, ONE, UC, uc, into} from "unchecked-counter/src/UC.sol";

library LibTradingConfig {

    bytes32 constant TRADING_CONFIG_POSITION = keccak256("apollox.trading.config.storage");

    // obsolete
    struct PriceProtection {
        uint40 updatedAt;
        uint64 upperPrice;  // 1e8
        uint64 lowerPrice;  // 1e8
    }

    struct TradingConfigStorage {
        uint256 executionFeeUsd;
        uint256 minNotionalUsd;
        uint24 maxTakeProfitP;
        // ITradingConfig.TradingSwitch
        uint16 tradingSwitches;
        mapping(address pairBase => PriceProtection) priceProtections;  // obsolete
        mapping(address pairBase => MaxTpRatioForLeverage[]) maxTpRatios;
        uint256 minBetUsd;
        address executionFeeReceiver;
    }

    function tradingConfigStorage() internal pure returns (TradingConfigStorage storage tcs) {
        bytes32 position = TRADING_CONFIG_POSITION;
        assembly {
            tcs.slot := position
        }
    }

    event SetTradeSwitches(uint16 indexed oldTradeSwitches, uint16 indexed tradeSwitches);
    event SetExecutionFeeUsd(uint256 oldExecutionFeeUsd, uint256 executionFeeUsd);
    event SetMinNotionalUsd(uint256 oldMinNotionalUsd, uint256 minNotionalUsd);
    event SetMinBetUsd(uint256 oldMinBetUsd, uint256 minBetUsd);
    event SetMaxTakeProfitP(uint24 oldMaxTakeProfitP, uint24 maxTakeProfitP);
    event SetMaxTpRatioForLeverage(address indexed pairBase, MaxTpRatioForLeverage[] maxTpRatios);

    function initialize(
        uint256 executionFeeUsd, uint256 minNotionalUsd, uint24 maxTakeProfitP, uint256 minBetUsd
    ) internal {
        TradingConfigStorage storage tcs = tradingConfigStorage();
        require(tcs.executionFeeUsd == 0 && tcs.minNotionalUsd == 0 && tcs.maxTakeProfitP == 0, "LibTradingConfig: Already initialized");
        setExecutionFeeUsd(executionFeeUsd);
        setMinNotionalUsd(minNotionalUsd);
        setMaxTakeProfitP(maxTakeProfitP);
        setMinBetUsd(minBetUsd);
        // 1+2+4+8+16+32+64+128 = 255
        setTradingSwitches(255);
    }

    function setTradingSwitches(uint16 switches) internal {
        TradingConfigStorage storage tcs = tradingConfigStorage();
        uint16 old = tcs.tradingSwitches;
        require(old != switches, "LibTradingConfig: No switches are updated");
        tcs.tradingSwitches = switches;
        emit SetTradeSwitches(old, switches);
    }

    function setExecutionFeeUsd(uint256 executionFeeUsd) internal {
        TradingConfigStorage storage tcs = tradingConfigStorage();
        uint256 oldExecutionFeeUsd = tcs.executionFeeUsd;
        tcs.executionFeeUsd = executionFeeUsd;
        emit SetExecutionFeeUsd(oldExecutionFeeUsd, executionFeeUsd);
    }

    function setMinNotionalUsd(uint256 minNotionalUsd) internal {
        require(minNotionalUsd > 0, "LibTradingConfig: minNotionalUsd must be greater than 0");
        TradingConfigStorage storage tcs = tradingConfigStorage();
        uint256 old = tcs.minNotionalUsd;
        tcs.minNotionalUsd = minNotionalUsd;
        emit SetMinNotionalUsd(old, minNotionalUsd);
    }

    function setMinBetUsd(uint256 minBetUsd) internal {
        require(minBetUsd > 0, "LibTradingConfig: minBetUsd must be greater than 0");
        TradingConfigStorage storage tcs = tradingConfigStorage();
        uint256 old = tcs.minBetUsd;
        tcs.minBetUsd = minBetUsd;
        emit SetMinBetUsd(old, minBetUsd);
    }

    function setMaxTakeProfitP(uint24 maxTakeProfitP) internal {
        require(maxTakeProfitP > 0, "LibTradingConfig: maxTakeProfitP must be greater than 0");
        TradingConfigStorage storage tcs = tradingConfigStorage();
        uint24 old = tcs.maxTakeProfitP;
        tcs.maxTakeProfitP = maxTakeProfitP;
        emit SetMaxTakeProfitP(old, maxTakeProfitP);
    }

    function setMaxTpRatioForLeverage(address pairBase, MaxTpRatioForLeverage[] calldata maxTpRatios) internal {
        delete tradingConfigStorage().maxTpRatios[pairBase];
        MaxTpRatioForLeverage[] storage tpRatios = tradingConfigStorage().maxTpRatios[pairBase];
        UC size = uc(maxTpRatios.length);
        for (UC i = ZERO; i < size; i = i + ONE) {
            MaxTpRatioForLeverage calldata tpRatio = maxTpRatios[i.into()];
            if (i + ONE < size) {
                MaxTpRatioForLeverage calldata nextTpRatio = maxTpRatios[(i + ONE).into()];
                require(tpRatio.leverage < nextTpRatio.leverage, "LibTradingConfig: leverage multipliers need to be in the order from smallest to largest");
            }
            tpRatios.push(tpRatio);
        }
        emit SetMaxTpRatioForLeverage(pairBase, maxTpRatios);
    }
}
"
    },
    "contracts/diamond/libraries/LibTradingCore.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../interfaces/ITradingCore.sol";
import {PairMaxOiAndFundingFeeConfig, IPairsManager} from "../interfaces/IPairsManager.sol";
import "@openzeppelin/contracts/utils/math/SignedMath.sol";

library LibTradingCore {

    using SignedMath for int256;

    bytes32 constant TRADING_CORE_POSITION = keccak256("apollox.trading.core.storage");

    struct TradingCoreStorage {
        // pair.pairBase =>
        mapping(address => ITradingCore.PairPositionInfo) pairPositionInfos;
        // pair.base[]
        address[] hasPositionPairs;
    }

    function tradingCoreStorage() internal pure returns (TradingCoreStorage storage tcs) {
        bytes32 position = TRADING_CORE_POSITION;
        assembly {
            tcs.slot := position
        }
    }

    function fundingFeeRate(
        ITradingCore.PairPositionInfo memory ppi, address pairBase
    ) internal view returns (int256) {
        PairMaxOiAndFundingFeeConfig memory pairConfig = IPairsManager(address(this)).getPairConfig(pairBase);
        int256 fundingFeeR;
        if (ppi.longQty != ppi.shortQty) {
            fundingFeeR = int256((int256(ppi.longQty) - int256(ppi.shortQty)).abs() * pairConfig.fundingFeePerBlockP) / (int256(ppi.longQty).max(int256(ppi.shortQty)));
            fundingFeeR = int256(pairConfig.maxFundingFeeR).min(int256(pairConfig.minFundingFeeR).max(fundingFeeR));
            if (ppi.longQty < ppi.shortQty) {
                fundingFeeR *= (- 1);
            }
        }
        return fundingFeeR;
    }
}
"
